let gamesRendered=false,currentGame='wordwall',boardIndex=-1,scores={g1:0,g2:0,g3:0,g4:0,g5:0,g6:0},timerSeconds=60,timerHandle=null;
function renderGames(){
 if(gamesRendered)return; gamesRendered=true;
 const grid=$('#gamesGrid'); if(!grid)return;
 BOARD_GAMES.forEach(g=>{const el=document.createElement('article');el.className='game-card';el.dataset.game=g.id;el.innerHTML=`<span class="game-icon">${g.icon}</span><h3>${lang==='ar'?g.arTitle:g.enTitle}</h3><p>${lang==='ar'?g.arDesc:g.enDesc}</p><span class="play-now">${lang==='ar'?'ابدئي اللعب ←':'Play now →'}</span>`;el.addEventListener('click',()=>openGame(g.id));grid.appendChild(el)})
}
function openGame(id){currentGame=id;boardIndex=-1;scores={g1:0,g2:0,g3:0,g4:0,g5:0,g6:0};updateScores();resetTimer();const g=BOARD_GAMES.find(x=>x.id===id);$('#boardGameType').textContent=lang==='ar'?'لعبة سبورة تفاعلية':'Interactive Board Game';$('#boardGameTitle').textContent=lang==='ar'?g.arTitle:g.enTitle;nextBoardItem();const m=$('#gameModal');m.classList.add('show');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeGame(){clearInterval(timerHandle);timerHandle=null;const m=$('#gameModal');m.classList.remove('show');m.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function updateScores(){Object.entries(scores).forEach(([key,value])=>{const el=document.getElementById('score'+key.toUpperCase());if(el)el.textContent=value})}
function resetTimer(){clearInterval(timerHandle);timerHandle=null;timerSeconds=60;$('#timerValue').textContent=timerSeconds;$('#timerStart').textContent='▶'}
function toggleTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null;$('#timerStart').textContent='▶';return}$('#timerStart').textContent='Ⅱ';timerHandle=setInterval(()=>{timerSeconds--;$('#timerValue').textContent=timerSeconds;if(timerSeconds<=0){clearInterval(timerHandle);timerHandle=null;$('#timerStart').textContent='▶'}},1000)}
function sample(arr){return arr[Math.floor(Math.random()*arr.length)]}
function baseBoard(chip,prompt,sub='',answer=''){return `<div class="board-main"><span class="board-chip">${chip}</span><div class="board-prompt">${prompt}</div>${sub?`<p class="board-subprompt">${sub}</p>`:''}${answer?`<div id="boardAnswer" class="board-answer">${answer}</div>`:''}</div>`}
function nextBoardItem(){resetTimer();const c=$('#boardContent');$('#boardReveal').style.display='inline-flex';
 if(currentGame==='wordwall'){const pick=sample(CHARTER_WORDS);const words=CHARTER_WORDS.map(w=>w[lang==='ar'?0:1]);c.innerHTML=`<div class="board-main"><span class="board-chip">${lang==='ar'?'جدار الميثاق':'Charter Word Wall'}</span><div class="word-wall-cloud">${words.map(w=>`<button class="wall-word ${w===(lang==='ar'?pick[0]:pick[1])?'active':''}">${w}</button>`).join('')}</div><p class="board-subprompt" style="margin-top:28px">${lang==='ar'?'الفريق: اشرحوا الكلمة المضيئة، أعطوا مثالاً مدرسياً، ثم حددوا محور الميثاق.':'Team: explain the highlighted word, give a school example, then identify its Charter axis.'}</p></div>`;$('#boardReveal').style.display='none';return}
 if(currentGame==='crossword'){c.innerHTML=`<div class="board-main"><span class="board-chip">${lang==='ar'?'8 أدلة • سباق الفرق':'8 clues • Team race'}</span><div class="crossword-grid">${CROSSWORD.map(x=>`<div class="cross-clue"><b>${x[0]}</b><p>${lang==='ar'?x[1]:x[3]}</p><span class="cross-answer">${lang==='ar'?x[2]:x[4]}</span></div>`).join('')}</div></div>`;return}
 if(currentGame==='qa'){const x=sample(QA_ITEMS);c.innerHTML=baseBoard(lang==='ar'?'سؤال الفريق':'Team Question',lang==='ar'?x.q:x.qe,lang==='ar'?'فكّروا، اتفقوا على إجابة، ثم اشرحوا السبب.':'Think, agree on an answer, then explain why.',lang==='ar'?x.a:x.ae);return}
 if(currentGame==='riddles'){const x=sample(RIDDLES);c.innerHTML=baseBoard(lang==='ar'?'لغز الميثاق':'Charter Riddle',lang==='ar'?x.q:x.qe,lang==='ar'?'ما العنصر؟':'Which element?',lang==='ar'?x.a:x.ae);return}
 if(currentGame==='drawing'){const x=sample(DRAWING);c.innerHTML=baseBoard(lang==='ar'?'ارسم دون كتابة كلمات':'Draw without writing words',lang==='ar'?x[2]:x[3],lang==='ar'?'المجموعة الأخرى تخمن عنصر الميثاق قبل انتهاء الوقت.':'The other team guesses the Charter element before time runs out.',lang==='ar'?x[0]:x[1]);return}
 if(currentGame==='discussion'){const x=sample(DISCUSSIONS);c.innerHTML=baseBoard(lang==='ar'?'ناقشوا ثم قرروا':'Discuss, then decide',lang==='ar'?x.q:x.qe,lang==='ar'?'30 ثانية للتفكير + 60 ثانية للنقاش. لا توجد إجابة من كلمة واحدة.':'30 seconds to think + 60 seconds to discuss. No one-word answers.',lang==='ar'?x.a:x.ae);return}
}
function revealBoard(){if(currentGame==='crossword'){$$('.cross-clue').forEach(x=>x.classList.add('revealed'));return}$('#boardAnswer')?.classList.add('show')}
$$('[data-close-game]').forEach(x=>x.addEventListener('click',closeGame));
$('#boardNext')?.addEventListener('click',nextBoardItem);$('#boardReveal')?.addEventListener('click',revealBoard);$('#timerStart')?.addEventListener('click',toggleTimer);$('#timerReset')?.addEventListener('click',resetTimer);
$$('[data-score]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.score,delta=Number(b.dataset.delta)||0;if(!(key in scores))return;scores[key]=Math.max(0,scores[key]+delta);updateScores()}));
$('#boardFullscreen')?.addEventListener('click',()=>{const el=$('.board-stage');if(!document.fullscreenElement)el?.requestFullscreen?.();else document.exitFullscreen?.()});

function renderPopupWordWall(){
 const box=$('#popupWordWall'); if(!box)return;
 const groups=[
  {ar:'الهوية الوطنية',en:'National Identity',items:CHARTER_WORDS.slice(0,9)},
  {ar:'السمات',en:'Traits',items:CHARTER_WORDS.slice(9,15)},
  {ar:'المهارات',en:'Skills',items:CHARTER_WORDS.slice(15)}
 ];
 box.innerHTML=groups.map(g=>`<section class="popup-word-group"><h4>${lang==='ar'?g.ar:g.en}</h4><div>${g.items.map(w=>`<button type="button" class="popup-wall-word">${w[lang==='ar'?0:1]}</button>`).join('')}</div></section>`).join('');
}
function openWordWallPopup(){renderPopupWordWall();const p=$('#wordWallPopup');p?.classList.add('show');p?.setAttribute('aria-hidden','false')}
function closeWordWallPopup(){const p=$('#wordWallPopup');p?.classList.remove('show');p?.setAttribute('aria-hidden','true')}
$('#boardWordWall')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();openWordWallPopup()});
$$('[data-close-wordwall]').forEach(x=>x.addEventListener('click',closeWordWallPopup));

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#wordWallPopup')?.classList.contains('show')){closeWordWallPopup();return}if(e.key==='Escape'&&$('#gameModal')?.classList.contains('show'))closeGame()});
